import { makeAutoObservable } from 'mobx'
import { menus } from '@/data/router'
import { getAdminUserDetail } from '@/apis/admin/permission'
import { storage } from '@/utils/Storage'
import { session } from '@/utils/Session'
import type { RouteType } from '@/routes'

class GlobalUser {
  /** 用户信息 */
  userInfo: Partial<AdminUser.UserInfoResponse> = {
    menus: []
  }

  /** 权限标识集合 */
  permissions: string[] = []

  /** 后端返回的菜单树 */
  menuTree: AdminUser.MenuTreeDto[] = []

  constructor() {
    makeAutoObservable(this)
  }

  /**
   * 检查是否有指定权限
   * @param perm 权限标识
   * @returns 是否有权限
   */
  hasPermission(perm: string): boolean {
    // 超级管理员拥有所有权限
    if (this.userInfo.roleId === 1) {
      return true
    }
    // 检查权限列表
    return this.permissions.includes(perm)
  }

  /**
   * 检查是否有任意一个权限
   * @param perms 权限标识数组
   * @returns 是否有任意一个权限
   */
  hasAnyPermission(perms: string[]): boolean {
    if (this.userInfo.roleId === 1) {
      return true
    }
    return perms.some(perm => this.permissions.includes(perm))
  }

  /**
   * 将后端菜单树转换为 ProLayout 路由格式
   * @param menuTree 后端菜单树
   * @returns ProLayout 路由配置
   */
  convertMenuTreeToRoutes(menuTree: AdminUser.MenuTreeDto[]): RouteType[] {
    const convert = (menus: AdminUser.MenuTreeDto[]): RouteType[] => {
      return menus
        .filter(menu => menu.status === 1) // 只显示启用的菜单
        .sort((a, b) => a.sort - b.sort) // 按排序值排序
        .map(menu => ({
          name: menu.name,
          path: menu.path,
          icon: menu.icon,
          component: menu.component,
          // 如果有子菜单，递归转换
          children: menu.children?.length ? convert(menu.children) : undefined
        }))
    }
    return convert(menuTree)
  }

  /**
   * 获取有效的菜单数据（优先使用后端菜单，否则使用本地过滤后的菜单）
   */
  getEffectiveMenus(): any[] {
    // 如果后端返回了菜单树，优先使用
    if (this.menuTree.length > 0) {
      return this.convertMenuTreeToRoutes(this.menuTree)
    }
    // 否则使用本地菜单（基于角色过滤）
    const isAdmin = this.userInfo?.roleId === 1
    return menus.filter(m => {
      if (m.adminOnly) {
        return isAdmin
      }
      if (m.nomalOnly) {
        return !isAdmin
      }
      return true
    })
  }

  /**
   * 设置登录返回的权限和菜单数据
   */
  setLoginData(data: { permissions?: string[]; menuTree?: AdminUser.MenuTreeDto[] }) {
    if (data.permissions) {
      this.permissions = data.permissions
    }
    if (data.menuTree) {
      this.menuTree = data.menuTree
    }
  }

  async getUserDetail() {
    try {
      // 从 storage 获取当前用户ID
      const userId = storage.get('userId') || session.get('userId')
      if (!userId) {
        console.error('用户ID不存在')
        return
      }
      const res = await getAdminUserDetail(Number(userId))
      const isAdmin = res?.data?.roleId === 1
      // 修复权限过滤逻辑
      const filterRuleMenus = menus.filter(m => {
        // 如果菜单标记为仅管理员可见，检查是否为管理员
        if (m.adminOnly) {
          return isAdmin
        }
        // 如果菜单标记为仅普通用户可见，检查是否为普通用户
        if (m.nomalOnly) {
          return !isAdmin
        }
        // 没有特殊标记的菜单，所有用户都可见
        return true
      })
      // 构造符合 AdminUser.UserInfoResponse 的数据结构
      this.userInfo = {
        ...res.data,
        menus: filterRuleMenus
      }
    } catch (error) {
      console.error('获取用户信息失败:', error)
    }
  }

  setUserInfo(user: Partial<AdminUser.UserInfoResponse>) {
    this.userInfo = user
  }

  /**
   * 清除用户相关数据（用于登出）
   */
  clearUserData() {
    this.userInfo = { menus: [] }
    this.permissions = []
    this.menuTree = []
  }
}

export const storeGlobalUser = new GlobalUser()
