import Axios from '@/server'
import type { Result } from '@/server/types'
import { PermissionTypes } from './types'

// ==================== 【角色管理】 ====================

/**
 * 【角色管理】获取角色权限配置
 * @param roleId 角色ID
 */
export const getRolePermissionsDetail = (roleId: number) =>
  Axios.request<Result<PermissionTypes.DetailAdminRolePermissionsRes>>({
    url: `/admin/permission/admin-role/${roleId}/role-permissions-detail`,
    method: 'GET'
  })

/**
 * 【角色管理】添加角色
 * @param data 角色信息
 */
export const addRole = (data: PermissionTypes.AddAdminRoleReq) =>
  Axios.request<Result>({
    url: '/admin/permission/admin-role/add',
    method: 'POST',
    data
  })

/**
 * 【角色管理】后台角色列表
 */
export const getRoleList = () =>
  Axios.request<Result<PermissionTypes.AdminRoleListRes>>({
    url: '/admin/permission/admin-role/list',
    method: 'GET'
  })

/**
 * 【角色管理】获取菜单功能权限列表
 */
export const getRolePermissionsList = () =>
  Axios.request<Result<PermissionTypes.AdminRolePermissionsListRes>>({
    url: '/admin/permission/admin-role/role-permissions-list',
    method: 'GET'
  })

