import { Card, Button, Space } from 'antd'
import { Line } from '@ant-design/plots'
import { useState, useMemo } from 'react'
import { createStyles } from 'antd-style'

const useStyles = createStyles(({ token }) => ({
  chartCard: {
    borderRadius: '12px'
  },
  cardHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '16px'
  },
  cardTitle: {
    fontSize: '16px',
    fontWeight: 600,
    color: token.colorTextHeading
  },
  activeBtn: {
    background: token.colorPrimary,
    color: '#fff',
    borderColor: token.colorPrimary
  }
}))

interface OrderTrendData {
  date: string
  type: string
  value: number
}

interface OrderTrendChartProps {
  loading?: boolean
  data?: {
    storedItems: { date: string; value: number }[]
    pickup: { date: string; value: number }[]
  }
}

const OrderTrendChart: React.FC<OrderTrendChartProps> = ({ 
  loading = false,
  data = { storedItems: [], pickup: [] }
}) => {
  const { styles } = useStyles()
  const [days, setDays] = useState(7)

  // 使用传入的数据
  const chartData = useMemo(() => {
    const result: OrderTrendData[] = []
    
    // 处理存件订单数据
    data.storedItems?.forEach((item) => {
      result.push({
        date: item.date,
        type: '存件订单',
        value: item.value || 0
      })
    })

    // 处理取件订单数据
    data.pickup?.forEach((item) => {
      result.push({
        date: item.date,
        type: '取件订单',
        value: item.value || 0
      })
    })

    return result
  }, [data])

  const handleDaysChange = (newDays: number) => {
    setDays(newDays)
    // TODO: 需要父组件重新获取对应天数的数据
  }

  const config = {
    data: chartData,
    xField: 'date',
    yField: 'value',
    colorField: 'type',
    shapeField: 'smooth',
    height: 280,
    legend: {
      position: 'bottom',
      offsetY: 10
    },
    tooltip: {
      shared: true,
      showMarkers: true
    },
    scale: {
      color: {
        range: ['#2563EB', '#10B981']
      }
    },
    style: {
      lineWidth: 2
    },
    area: {
      style: {
        fillOpacity: 0.15
      }
    },
    interaction: {
      tooltip: {
        marker: true
      }
    }
  }

  return (
    <Card className={styles.chartCard} loading={loading} variant="borderless">
      <div className={styles.cardHeader}>
        <span className={styles.cardTitle}>订单趋势图</span>
        <Space size="small">
          <Button
            size="small"
            type={days === 7 ? 'primary' : 'default'}
            onClick={() => handleDaysChange(7)}
          >
            近7天
          </Button>
          <Button
            size="small"
            type={days === 30 ? 'primary' : 'default'}
            onClick={() => handleDaysChange(30)}
          >
            近30天
          </Button>
          <Button
            size="small"
            type={days === 90 ? 'primary' : 'default'}
            onClick={() => handleDaysChange(90)}
          >
            近90天
          </Button>
        </Space>
      </div>
      <Line {...config} />
    </Card>
  )
}

export default OrderTrendChart