import Axios from '@/server'
import type { Result } from '@/server/types'
import { HomepageTypes } from './types'

// ==================== 【柜子趋势数据】====================

/**
 * 【柜子趋势数据】获取柜子使用率趋势数据
 * @param params 查询参数
 */
export const getCabinetTrend = (params: HomepageTypes.CabinetTrendReq) =>
  Axios.request<Result<HomepageTypes.CabinetTrendRes>>({
    url: '/admin/home-page/cabinet-trend/day',
    method: 'GET',
    params
  })

