import { Card, Row, Col } from 'antd'
import {
  FileTextOutlined,
  DollarOutlined,
  ClockCircleOutlined,
  ArrowUpOutlined,
  ArrowDownOutlined,
  WarningOutlined
} from '@ant-design/icons'
import { createStyles } from 'antd-style'

const useStyles = createStyles(({ token, isDarkMode }) => ({
  statCard: {
    borderRadius: '12px',
    transition: 'all 0.3s ease',
    '&:hover': {
      transform: 'translateY(-4px)',
      boxShadow: isDarkMode ? '0 8px 24px rgba(0, 0, 0, 0.4)' : '0 8px 24px rgba(0, 0, 0, 0.08)'
    }
  },
  statIcon: {
    width: '56px',
    height: '56px',
    borderRadius: '12px',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    fontSize: '24px'
  },
  orderIcon: {
    background: token.colorPrimaryBg,
    color: token.colorPrimary
  },
  revenueIcon: {
    background: token.colorWarningBg,
    color: token.colorWarning
  },
  pendingIcon: {
    background: token.colorErrorBg,
    color: token.colorError
  },
  statValue: {
    fontSize: '32px',
    fontWeight: 700,
    marginTop: '8px'
  },
  statLabel: {
    fontSize: '14px',
    color: token.colorTextSecondary,
    marginBottom: '4px'
  },
  trend: {
    fontSize: '13px',
    display: 'flex',
    alignItems: 'center',
    gap: '4px',
    marginTop: '8px'
  },
  trendUp: {
    color: token.colorSuccess
  },
  trendDown: {
    color: token.colorError
  },
  trendWarning: {
    color: token.colorError
  }
}))

interface StatCardsProps {
  todayOrders: number
  todayRevenue: number
  pendingItems: number
  orderTrend: number
  revenueTrend: number
  loading?: boolean
}

const StatCards: React.FC<StatCardsProps> = ({
  todayOrders = 0,
  todayRevenue = 0,
  pendingItems = 0,
  orderTrend = 0,
  revenueTrend = 0,
  loading = false
}) => {
  const { styles, cx } = useStyles()

  // 判断趋势正负
  const isOrderTrendUp = orderTrend >= 0
  const isRevenueTrendUp = revenueTrend >= 0

  return (
    <Row gutter={[16, 16]} style={{ marginBottom: '20px' }}>
      <Col xs={24} sm={12} lg={8}>
        <Card className={styles.statCard} loading={loading} variant="borderless">
          <div style={{ display: 'flex', alignItems: 'flex-start', gap: '16px' }}>
            <div className={cx(styles.statIcon, styles.orderIcon)}>
              <FileTextOutlined />
            </div>
            <div style={{ flex: 1 }}>
              <div className={styles.statLabel}>今日订单量</div>
              <div className={styles.statValue}>{todayOrders}</div>
              <div className={cx(styles.trend, isOrderTrendUp ? styles.trendUp : styles.trendDown)}>
                {isOrderTrendUp ? <ArrowUpOutlined /> : <ArrowDownOutlined />}
                <span>{Math.abs(orderTrend)}% 较昨日</span>
              </div>
            </div>
          </div>
        </Card>
      </Col>

      <Col xs={24} sm={12} lg={8}>
        <Card className={styles.statCard} loading={loading} variant="borderless">
          <div style={{ display: 'flex', alignItems: 'flex-start', gap: '16px' }}>
            <div className={cx(styles.statIcon, styles.revenueIcon)}>
              <DollarOutlined />
            </div>
            <div style={{ flex: 1 }}>
              <div className={styles.statLabel}>今日营收金额</div>
              <div className={styles.statValue}>¥{todayRevenue.toLocaleString()}</div>
              <div className={cx(styles.trend, isRevenueTrendUp ? styles.trendUp : styles.trendDown)}>
                {isRevenueTrendUp ? <ArrowUpOutlined /> : <ArrowDownOutlined />}
                <span>{Math.abs(revenueTrend)}% 较昨日</span>
              </div>
            </div>
          </div>
        </Card>
      </Col>

      <Col xs={24} sm={12} lg={8}>
        <Card className={styles.statCard} loading={loading} variant="borderless">
          <div style={{ display: 'flex', alignItems: 'flex-start', gap: '16px' }}>
            <div className={cx(styles.statIcon, styles.pendingIcon)}>
              <ClockCircleOutlined />
            </div>
            <div style={{ flex: 1 }}>
              <div className={styles.statLabel}>滞留件数量</div>
              <div className={styles.statValue} style={{ color: '#EF4444' }}>
                {pendingItems}
              </div>
              <div className={cx(styles.trend, styles.trendWarning)}>
                <WarningOutlined />
                <span>待处理</span>
              </div>
            </div>
          </div>
        </Card>
      </Col>
    </Row>
  )
}

export default StatCards
