import { aesEcb } from '@/utils/encrypt'
import {
  accountLogin,
  phoneLogin,
  getLoginCaptcha,
  getPhoneVerificationCode,
  accountVerificationCode,
  superAdminAccountLogin
} from '@/apis/admin/site'
import { storeGlobalUser } from '@/store/globalUser'
import { storage } from '@/utils/Storage'
import { LoginFormPage, ProFormCheckbox, ProFormText, type ProFormInstance } from '@ant-design/pro-components'
import { useNavigate } from 'react-router-dom'
import LoginBg from '@/assets/login_bg.png'
import { useState, useEffect, useRef } from 'react'
import { message, Tabs, Button } from 'antd'
import { session } from '@/utils/Session'
import { redirectToHome } from '@/utils'
import { ResultEnum } from '@/utils/enums/httpEnum'
import { useUpdateEffect } from 'ahooks'

// 登录入口类型
type LoginEntryType = 'normal' | 'admin'
// 普通用户登录方式
type NormalLoginType = 'password' | 'phone'

const Login = () => {
  const navigate = useNavigate()
  const formRef = useRef<ProFormInstance>()

  // 入口类型：普通用户 / 超管
  const [entryType, setEntryType] = useState<LoginEntryType>('normal')
  // 普通用户登录方式
  const [loginType, setLoginType] = useState<NormalLoginType>('password')

  // 图片验证码相关
  const [count, setCount] = useState(0)
  const [captchaUrl, setCaptchaUrl] = useState<string | null>(null)
  const [cid, setCid] = useState<string>('')
  const timer = useRef<NodeJS.Timeout>()

  // 短信验证码相关
  const [smsCount, setSmsCount] = useState(0)
  const smsTimer = useRef<NodeJS.Timeout>()

  // 加载状态
  const [loading, setLoading] = useState(false)

  // 获取图片验证码
  const getCaptchaData = async () => {
    if (count > 0) {
      message.warning('验证码刷新太频繁，请稍后再试')
      return
    }
    const res = await getLoginCaptcha()
    if (res.code === ResultEnum.SUCCESS) {
      setCaptchaUrl(res.data.base64)
      setCid(res.data.cid)
    }
  }

  // 发送短信验证码
  const sendSmsCode = async (values: any) => {
    // 超管模式：通过用户名获取验证码
    if (entryType === 'admin') {
      const { userName } = values
      if (!userName) {
        message.warning('请先输入用户名')
        return
      }
      if (smsCount > 0) {
        message.warning(`请${smsCount}秒后再试`)
        return
      }
      try {
        const res = await accountVerificationCode({
          account: userName,
          bizCode: 'adminLogin',
          bizType: 'admin'
        })
        if (res.code === ResultEnum.SUCCESS) {
          message.success('验证码已发送至绑定手机号')
          setSmsCount(60)
        } else {
          message.error(res.message || '发送失败')
        }
      } catch (e) {
        message.error('发送失败，请重试')
      }
      return
    }

    // 普通用户模式：通过手机获取验证码
    const { phone } = values
    if (!phone) {
      message.warning('请输入手机号')
      return
    }
    if (smsCount > 0) {
      message.warning(`请${smsCount}秒后再试`)
      return
    }
    try {
      const res = await getPhoneVerificationCode({
        phone,
        bizCode: 'adminLogin',
        bizType: 'admin'
      })
      if (res.code === ResultEnum.SUCCESS) {
        message.success('验证码已发送')
        setSmsCount(60)
      } else {
        message.error(res.message || '发送失败')
      }
    } catch (e) {
      message.error('发送失败，请重试')
    }
  }

  // 保存登录信息
  const saveLoginInfo = (res: any, autoLogin: boolean) => {
    if (autoLogin) {
      storage.set('token', res.data?.token)
      storage.set('userId', res.data?.id)
    } else {
      storage.remove('token')
      storage.remove('userId')
      session.set('token', res.data?.token)
      session.set('userId', res.data?.id)
    }
  }

  // 登录成功后的处理
  const handleLoginSuccess = async (res: any, navigate: any) => {
    // 存储登录返回的权限和菜单数据
    storeGlobalUser.setLoginData({
      permissions: res.data?.permissions || [],
      menuTree: res.data?.menuTree || []
    })
    redirectToHome(storeGlobalUser?.userInfo?.roleId, navigate)
  }

  // 普通用户登录
  const handleNormalLogin = async (values: any) => {
    console.log('handleNormalLogin', values)
    setLoading(true)
    try {
      let res
      if (loginType === 'password') {
        // 账号密码登录
        const { userName, password, code } = values
        const encryptedPassword = aesEcb.encrypt(password)
        res = await accountLogin({
          userName,
          cid,
          code,
          password: encryptedPassword
        })
      } else {
        // 手机验证码登录
        const { phone, smsCode } = values
        res = await phoneLogin({
          phone,
          code: smsCode
        })
      }

      if (res.code === ResultEnum.SUCCESS) {
        saveLoginInfo(res, values.autoLogin)
        message.success('登录成功')
        await handleLoginSuccess(res, navigate)
      } else {
        message.error(res.message || '登录失败')
        if (loginType === 'password') {
          await getCaptchaData()
        }
      }
    } catch (e) {
      message.error('登录失败，请重试')
      if (loginType === 'password') {
        await getCaptchaData()
      }
    } finally {
      setLoading(false)
    }
  }

  // 超管双重验证登录
  const handleAdminLogin = async (values: any) => {
    setLoading(true)
    try {
      const { userName, password, code: captchaCode, smsCode } = values

      // 密码加密
      const encryptedPassword = aesEcb.encrypt(password)

      // 调用超管统一登录接口
      const res = await superAdminAccountLogin({
        userName,
        password: encryptedPassword,
        cid,
        code: captchaCode,
        phoneCode: smsCode
      })

      if (res.code === ResultEnum.SUCCESS) {
        // 超管登录不使用自动登录，始终使用 session 存储
        saveLoginInfo(res, false)
        message.success('登录成功')
        await handleLoginSuccess(res, navigate)
      } else {
        message.error(res.message || '登录失败')
        await getCaptchaData()
      }
    } catch (e) {
      message.error('登录失败，请重试')
      await getCaptchaData()
    } finally {
      setLoading(false)
    }
  }

  // 处理登录提交
  const handleLogin = async (values: any) => {
    console.log('handleLogin',values)
    if (entryType === 'admin') {
      await handleAdminLogin(values)
    } else {
      await handleNormalLogin(values)
    }
  }

  // 切换入口类型时重置验证码
  useUpdateEffect(() => {
    if (entryType === 'normal' || entryType === 'admin') {
      getCaptchaData()
    }
  }, [entryType])

  useEffect(() => {
    getCaptchaData()
  }, [])

  useEffect(() => {
    if (captchaUrl) {
      setCount(1)
    }
  }, [captchaUrl])

  useEffect(() => {
    if (count > 0) {
      timer.current = setInterval(() => {
        setCount(count - 1)
      }, 1000)
      if (count <= 0) {
        clearInterval(timer.current)
      }
    }
    return () => clearInterval(timer.current)
  }, [count])

  useEffect(() => {
    if (smsCount > 0) {
      smsTimer.current = setInterval(() => {
        setSmsCount(prev => prev - 1)
      }, 1000)
    } else {
      clearInterval(smsTimer.current)
    }
    return () => clearInterval(smsTimer.current)
  }, [smsCount])

  // 切换登录方式
  const switchLoginType = (type: NormalLoginType) => {
    setLoginType(type)
    // 切换时重置表单
    formRef.current?.resetFields()
  }

  // 渲染普通用户登录表单
  const renderNormalLoginForm = () => (
    <>
      {/* 自定义标签切换 */}
      <div style={{ display: 'flex', justifyContent: 'center', marginBottom: 24, borderBottom: '1px solid #f0f0f0' }}>
        <div
          onClick={() => switchLoginType('password')}
          style={{
            padding: '12px 24px',
            cursor: 'pointer',
            borderBottom: loginType === 'password' ? '2px solid #1890ff' : '2px solid transparent',
            color: loginType === 'password' ? '#1890ff' : '#666',
            fontWeight: loginType === 'password' ? 500 : 400,
            transition: 'all 0.3s'
          }}
        >
          账号密码登录
        </div>
        <div
          onClick={() => switchLoginType('phone')}
          style={{
            padding: '12px 24px',
            cursor: 'pointer',
            borderBottom: loginType === 'phone' ? '2px solid #1890ff' : '2px solid transparent',
            color: loginType === 'phone' ? '#1890ff' : '#666',
            fontWeight: loginType === 'phone' ? 500 : 400,
            transition: 'all 0.3s'
          }}
        >
          手机验证码登录
        </div>
      </div>

      {/* 账号密码登录表单 */}
      {loginType === 'password' && (
        <>
          <ProFormText
            name="userName"
            fieldProps={{
              size: 'large',
            }}
            placeholder={'用户名'}
            rules={[{ required: true, message: '请输入用户名!' }]}
          />
          <ProFormText.Password
            name="password"
            fieldProps={{
              size: 'large',
            }}
            placeholder={'密码'}
            rules={[{ required: true, message: '请输入密码！' }]}
          />
          <div style={{ display: 'flex', gap: 8 }}>
            <ProFormText
              name="code"
              fieldProps={{
                size: 'large',
                style: { flex: 1 }
              }}
              placeholder={'验证码'}
              rules={[{ required: true, message: '请输入验证码！' }]}
            />
            {captchaUrl && (
              <img
                src={captchaUrl}
                alt="验证码"
                onClick={getCaptchaData}
                style={{
                  width: '100%',
                  maxHeight: 40,
                  marginBottom: 8,
                  cursor: 'pointer',
                  borderRadius: 4
                }}
              />
            )}
          </div>
        </>
      )}

      {/* 手机验证码登录表单 */}
      {loginType === 'phone' && (
        <>
          <ProFormText
            name="phone"
            fieldProps={{
              size: 'large',
            }}
            placeholder={'手机号'}
            rules={[
              { required: true, message: '请输入手机号!' },
              { pattern: /^1\d{10}$/, message: '请输入正确的手机号!' }
            ]}
          />
          <div style={{ display: 'flex', gap: 8 }}>
            <ProFormText
              name="smsCode"
              fieldProps={{
                size: 'large',
                style: { flex: 1 }
              }}
              placeholder={'短信验证码'}
              rules={[{ required: true, message: '请输入短信验证码！' }]}
            />
            <Button
              style={{ marginBottom: 24, height: 40 }}
              disabled={smsCount > 0}
              onClick={() => {
                const values = formRef.current?.getFieldsValue()
                if (values?.phone) {
                  sendSmsCode(values)
                } else {
                  message.warning('请输入手机号')
                }
              }}
            >
              {smsCount > 0 ? `${smsCount}s后重试` : '获取验证码'}
            </Button>
          </div>
        </>
      )}

      <div style={{ marginBlockEnd: 24 }}>
        <ProFormCheckbox noStyle name="autoLogin">
          自动登录
        </ProFormCheckbox>
      </div>
    </>
  )

  // 渲染超管登录表单
  const renderAdminLoginForm = () => (
    <>
      <div style={{ marginBottom: 16 }}>
        <ProFormText
          name="userName"
          fieldProps={{
            size: 'large',
          }}
          placeholder={'用户名'}
          rules={[{ required: true, message: '请输入用户名!' }]}
        />
        <ProFormText.Password
          name="password"
          fieldProps={{
            size: 'large',
          }}
          placeholder={'密码'}
          rules={[{ required: true, message: '请输入密码！' }]}
        />
        <div style={{ display: 'flex', gap: 8 }}>
          <ProFormText
            name="code"
            fieldProps={{
              size: 'large',
              style: { flex: 1 }
            }}
            placeholder={'图片验证码'}
            rules={[{ required: true, message: '请输入验证码！' }]}
          />
          {captchaUrl && (
            <img
              src={captchaUrl}
              alt="验证码"
              onClick={getCaptchaData}
              style={{
                width: '100%',
                maxHeight: 40,
                marginBottom: 8,
                cursor: 'pointer',
                borderRadius: 4
              }}
            />
          )}
        </div>
        <div style={{ display: 'flex', gap: 8 }}>
          <ProFormText
            name="smsCode"
            fieldProps={{
              size: 'large',
              style: { flex: 1 }
            }}
            placeholder={'短信验证码'}
            rules={[{ required: true, message: '请输入短信验证码！' }]}
          />
          <Button
            style={{ marginBottom: 24, height: 40 }}
            disabled={smsCount > 0}
            onClick={() => {
              const values = formRef.current?.getFieldsValue()
              if (values?.userName) {
                sendSmsCode(values)
              } else {
                message.warning('请先输入用户名')
              }
            }}
          >
            {smsCount > 0 ? `${smsCount}s后重试` : '获取验证码'}
          </Button>
        </div>
      </div>
    </>
  )

  return (
    <div style={{ backgroundColor: 'white', height: '100vh' }}>
      <LoginFormPage
        formRef={formRef}
        backgroundImageUrl={LoginBg}
        title="XLINK"
        subTitle="祥云设备管理平台"
        onFinish={handleLogin}
        submitter={{
          searchConfig: {
            submitText: '登录'
          },
          submitButtonProps: {
            loading,
            size: 'large',
            style: { width: '100%' }
          }
        }}
        actions={
          <div style={{ display: 'flex', justifyContent: 'center', marginTop: 16 }}>
            <Button
              type={entryType === 'normal' ? 'primary' : 'default'}
              onClick={() => setEntryType('normal')}
              style={{ marginRight: 8, flex: 1 }}
            >
              普通用户登录
            </Button>
            <Button
              type={entryType === 'admin' ? 'primary' : 'default'}
              onClick={() => setEntryType('admin')}
              danger={entryType === 'admin'}
              style={{ flex: 1 }}
            >
              超级管理员登录
            </Button>
          </div>
        }
      >
        {entryType === 'normal' ? renderNormalLoginForm() : renderAdminLoginForm()}
      </LoginFormPage>
    </div>
  )
}

export default Login
