import { Card, Button, Space } from 'antd'
import { Line } from '@ant-design/plots'
import { useState, useMemo } from 'react'
import { createStyles } from 'antd-style'

const useStyles = createStyles(({ token }) => ({
  chartCard: {
    borderRadius: '12px'
  },
  cardHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '16px'
  },
  cardTitle: {
    fontSize: '16px',
    fontWeight: 600,
    color: token.colorTextHeading
  }
}))

interface UsageTrendData {
  date: string
  value: number
}

interface UsageTrendChartProps {
  loading?: boolean
  data?: { date: string; value: number }[]
}

const UsageTrendChart: React.FC<UsageTrendChartProps> = ({ 
  loading = false,
  data = []
}) => {
  const { styles } = useStyles()
  const [days, setDays] = useState(7)

  // 使用传入的数据
  const chartData = useMemo(() => {
    return data.map(item => ({
      date: item.date,
      value: item.value || 0
    }))
  }, [data])

  const handleDaysChange = (newDays: number) => {
    setDays(newDays)
    // TODO: 需要父组件重新获取对应天数的数据
  }

  const config = {
    data: chartData,
    xField: 'date',
    yField: 'value',
    shapeField: 'smooth',
    height: 280,
    tooltip: {
      formatter: (datum: UsageTrendData) => {
        return {
          name: '平均使用率',
          value: `${datum.value}%`
        }
      }
    },
    scale: {
      y: {
        min: 0,
        max: 100,
        tickCount: 5
      }
    },
    axis: {
      y: {
        labelFormatter: (v: number) => `${v}%`
      }
    },
    style: {
      stroke: '#F59E0B',
      lineWidth: 2
    },
    area: {
      style: {
        fill: 'l(90) 0:rgba(245,158,11,0.2) 1:rgba(245,158,11,0)'
      }
    }
  }

  return (
    <Card className={styles.chartCard} loading={loading} variant="borderless">
      <div className={styles.cardHeader}>
        <span className={styles.cardTitle}>柜子使用率趋势图</span>
        <Space size="small">
          <Button
            size="small"
            type={days === 7 ? 'primary' : 'default'}
            onClick={() => handleDaysChange(7)}
          >
            近7天
          </Button>
          <Button
            size="small"
            type={days === 30 ? 'primary' : 'default'}
            onClick={() => handleDaysChange(30)}
          >
            近30天
          </Button>
          <Button
            size="small"
            type={days === 90 ? 'primary' : 'default'}
            onClick={() => handleDaysChange(90)}
          >
            近90天
          </Button>
        </Space>
      </div>
      <Line {...config} />
    </Card>
  )
}

export default UsageTrendChart