import { Modal, Button, message } from 'antd'
import { SettingOutlined } from '@ant-design/icons'
import {
    ProForm,
    ProFormInstance,
    ProFormText
} from '@ant-design/pro-components'
import { useRef } from 'react'
import { ResultEnum } from '@/utils/enums/httpEnum'
import { storage } from '@/utils/Storage'
import { session } from '@/utils/Session'
import { useNavigate } from 'react-router-dom'
import { observer } from 'mobx-react'
import { updateUserPassword } from '@/apis/admin/permission'

interface ChangePasswordModalProps {
    children?: React.ReactNode
    /** 修改成功后的回调 */
    onSuccess?: () => void
}

const ChangePasswordModal: React.FC<ChangePasswordModalProps> = observer(({ children, onSuccess }) => {
    const modalFormRef = useRef<ProFormInstance>()
    const navigate = useNavigate()

    const onSubmit = async () => {
        const val = await modalFormRef?.current?.validateFields()
        if (val.newPassword.length < 6) {
            message.error('密码长度不能小于6位')
            return Promise.reject()
        }
        if (val.newPassword.length > 16) {
            message.error('密码长度不能大于16位')
            return Promise.reject()
        }
        if (val.newPassword !== val.confirmPassword) {
            message.error('两次输入的密码不一致')
            return Promise.reject()
        }

        try {
            const res = await updateUserPassword({
                password: val.newPassword,
                password2: val.confirmPassword
            })

            if (res.code === ResultEnum.SUCCESS) {
                message.success('密码修改成功，请重新登录')
                onSuccess?.()
                // 清除登录信息并跳转到登录页
                storage.clear()
                session.clear()
                navigate('/login')
            } else {
                message.error(res.message || '密码修改失败')
                return Promise.reject()
            }
        } catch (error) {
            message.error('密码修改失败，请稍后重试')
            return Promise.reject()
        }
    }

    const showModal = () => {
        Modal.confirm({
            title: '修改密码',
            onOk: async () => onSubmit(),
            okText: '确定',
            cancelText: '取消',
            width: 600,
            content: (
                <ProForm
                    labelCol={{ span: 6 }}
                    wrapperCol={{ span: 10 }}
                    submitter={false}
                    layout="horizontal"
                    formRef={modalFormRef}
                >
                    <ProFormText
                        label="新密码"
                        name="newPassword"
                        rules={[{ required: true, message: '请输入新密码' }]}
                        fieldProps={{ type: 'password' }}
                    />
                    <ProFormText
                        label="再次确认密码"
                        name="confirmPassword"
                        rules={[{ required: true, message: '请再次确认密码' }]}
                        fieldProps={{ type: 'password' }}
                    />
                </ProForm>
            )
        })
    }

    return (
        <div onClick={() => showModal()}> {
            children ? children : <Button
                icon={<SettingOutlined />}
                shape="circle"
            />
        } </div>
    )
})

export default ChangePasswordModal
