import { GridContent } from '@ant-design/pro-components'
import { Row, Col, Card } from 'antd'
import { Suspense } from 'react'
import { useRequest } from 'ahooks'
import PageLoading from '@/components/PageLoading'
import StatCards from './components/StatCards'
import {
  getStatisticalRevenueData,
  getDeviceStatisticalData,
  getOrderTrend,
  getCabinetTrend,
  HomepageTypes
} from '@/apis/admin/homepage'
import { ResultEnum } from '@/utils/enums/httpEnum'
import dayjs from 'dayjs'

import OrderTrendChart from './components/OrderTrendChart'
import UsageTrendChart from './components/UsageTrendChart'
import RecentAlarms from './components/RecentAlarms'
import RecentOrders from './components/RecentOrders'
import DeviceStatusOverview from './components/DeviceStatusOverview'

// 图表数据项
interface ChartDataItem {
  date: string
  value: number
}

// 仪表盘数据类型定义
interface DashboardData {
  todayOrders: number
  yesterdayOrders: number
  todayRevenue: number
  yesterdayRevenue: number
  pendingItems: number
  orderTrend: number
  revenueTrend: number
  onlineNum: number
  offlineNum: number
  faultNum: number
  // 图表数据
  orderTrendData: {
    storedItems: ChartDataItem[]
    pickup: ChartDataItem[]
  }
  cabinetTrendData: ChartDataItem[]
}

// API 接口 - 获取所有仪表盘数据（包括图表）
const getDashboardData = async (): Promise<DashboardData> => {
  const [revenueRes, deviceRes, orderTrendRes, cabinetTrendRes] = await Promise.all([
    getStatisticalRevenueData(),
    getDeviceStatisticalData(),
    getOrderTrend({ dayNum: 7 }),
    getCabinetTrend({ dayNum: 7 })
  ])

  const revenueData = revenueRes.code === ResultEnum.SUCCESS ? revenueRes.data : null
  const deviceData = deviceRes.code === ResultEnum.SUCCESS ? deviceRes.data : null
  const orderTrendData = orderTrendRes.code === ResultEnum.SUCCESS ? orderTrendRes.data : null
  const cabinetTrendData = cabinetTrendRes.code === ResultEnum.SUCCESS ? cabinetTrendRes.data : null

  // 计算趋势百分比
  const orderTrend = revenueData?.todayOrderNum && revenueData?.yesterdayOrderNum
    ? Number((((revenueData.todayOrderNum - revenueData.yesterdayOrderNum) / revenueData.yesterdayOrderNum) * 100).toFixed(1))
    : 0

  const revenueTrend = revenueData?.todayRevenueAmount && revenueData?.yesterdayRevenueAmount
    ? Number((((revenueData.todayRevenueAmount - revenueData.yesterdayRevenueAmount) / revenueData.yesterdayRevenueAmount) * 100).toFixed(1))
    : 0

  // 处理图表数据
  const today = dayjs()
  const days = 7

  // 处理订单趋势数据
  const orderTrendChartData = {
    storedItems: [] as ChartDataItem[],
    pickup: [] as ChartDataItem[]
  }

  orderTrendData?.storedItems?.forEach((item, index) => {
    const date = today.subtract(days - 1 - index, 'day')
    orderTrendChartData.storedItems.push({
      date: date.format('MM-DD'),
      value: item.num || 0
    })
  })

  orderTrendData?.pickup?.forEach((item, index) => {
    const date = today.subtract(days - 1 - index, 'day')
    orderTrendChartData.pickup.push({
      date: date.format('MM-DD'),
      value: item.num || 0
    })
  })

  // 处理柜子使用率数据
  const cabinetTrendChartData: ChartDataItem[] = []
  cabinetTrendData?.items?.forEach((item, index) => {
    const date = today.subtract(days - 1 - index, 'day')
    cabinetTrendChartData.push({
      date: date.format('MM-DD'),
      value: item.num || 0
    })
  })

  return {
    todayOrders: revenueData?.todayOrderNum || 0,
    yesterdayOrders: revenueData?.yesterdayOrderNum || 0,
    todayRevenue: revenueData?.todayRevenueAmount || 0,
    yesterdayRevenue: revenueData?.yesterdayRevenueAmount || 0,
    pendingItems: revenueData?.detainNum || 0,
    orderTrend,
    revenueTrend,
    onlineNum: deviceData?.onlineNum || 0,
    offlineNum: deviceData?.offlineNum || 0,
    faultNum: deviceData?.faultNum || 0,
    orderTrendData: orderTrendChartData,
    cabinetTrendData: cabinetTrendChartData
  }
}

const Dashboard = () => {
  const { data, loading } = useRequest(getDashboardData, {
    defaultParams: [],
  })

  const statData = data || {
    todayOrders: 0,
    yesterdayOrders: 0,
    todayRevenue: 0,
    yesterdayRevenue: 0,
    pendingItems: 0,
    orderTrend: 0,
    revenueTrend: 0,
    onlineNum: 0,
    offlineNum: 0,
    faultNum: 0,
    orderTrendData: { storedItems: [], pickup: [] },
    cabinetTrendData: []
  }

  return (
    <GridContent>
      <Suspense fallback={<PageLoading />}>
        {/* 核心指标卡片 */}
        <StatCards
          todayOrders={statData.todayOrders}
          todayRevenue={statData.todayRevenue}
          pendingItems={statData.pendingItems}
          orderTrend={statData.orderTrend}
          revenueTrend={statData.revenueTrend}
          loading={loading}
        />

        {/* 图表行：订单趋势 + 柜子使用率趋势 */}
        <Row gutter={[16, 16]} style={{ marginBottom: '20px' }}>
          <Col xs={24} lg={12}>
            <Suspense fallback={<Card loading />}>
              <OrderTrendChart 
                loading={loading} 
                data={statData.orderTrendData}
              />
            </Suspense>
          </Col>
          <Col xs={24} lg={12}>
            <Suspense fallback={<Card loading />}>
              <UsageTrendChart 
                loading={loading} 
                data={statData.cabinetTrendData}
              />
            </Suspense>
          </Col>
        </Row>

        {/* 图表行：近期告警 + 近期订单 */}
        <Row gutter={[16, 16]} style={{ marginBottom: '20px' }}>
          <Col xs={24} lg={12}>
            <Suspense fallback={<Card loading />}>
              <RecentAlarms loading={loading} />
            </Suspense>
          </Col>
          <Col xs={24} lg={12}>
            <Suspense fallback={<Card loading />}>
              <RecentOrders loading={loading} />
            </Suspense>
          </Col>
        </Row>

        {/* 设备状态概览 */}
        <Row gutter={[16, 16]} style={{ marginBottom: '20px' }}>
          <Col span={24}>
            <Suspense fallback={<Card loading />}>
              <DeviceStatusOverview
                loading={loading}
                onlineNum={statData.onlineNum}
                offlineNum={statData.offlineNum}
                faultNum={statData.faultNum}
              />
            </Suspense>
          </Col>
        </Row>
      </Suspense>
    </GridContent>
  )
}

export default Dashboard
