import { Card, Table, Tag, Button } from 'antd'
import { RightOutlined } from '@ant-design/icons'
import { createStyles } from 'antd-style'
import type { ColumnsType } from 'antd/es/table'
import { useNavigate } from 'react-router-dom'

const useStyles = createStyles(({ token }) => ({
  card: {
    borderRadius: '12px',
    height: '100%'
  },
  cardHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '16px'
  },
  cardTitle: {
    fontSize: '16px',
    fontWeight: 600,
    color: token.colorTextHeading
  },
  linkBtn: {
    fontSize: '12px',
    padding: 0
  },
  table: {
    '& .ant-table-cell': {
      fontSize: '13px',
      padding: '12px 8px'
    }
  },
  timeCell: {
    fontSize: '12px',
    color: token.colorTextSecondary
  }
}))

interface AlarmItem {
  id: string
  time: string
  deviceName: string
  deviceCode: string
  type: 'offline' | 'cell_fault' | 'heartbeat_timeout'
  status: 'pending' | 'resolved'
}

// 模拟数据
const mockAlarms: AlarmItem[] = [
  {
    id: '1',
    time: '2026-04-03 09:30:00',
    deviceName: 'A区-01号柜',
    deviceCode: 'XL-001',
    type: 'offline',
    status: 'pending'
  },
  {
    id: '2',
    time: '2026-04-03 08:15:00',
    deviceName: 'B区-02号柜',
    deviceCode: 'XL-002',
    type: 'cell_fault',
    status: 'pending'
  },
  {
    id: '3',
    time: '2026-04-02 22:45:00',
    deviceName: 'C区-03号柜',
    deviceCode: 'XL-003',
    type: 'heartbeat_timeout',
    status: 'resolved'
  },
  {
    id: '4',
    time: '2026-04-02 18:20:00',
    deviceName: 'A区-05号柜',
    deviceCode: 'XL-005',
    type: 'cell_fault',
    status: 'resolved'
  },
  {
    id: '5',
    time: '2026-04-02 14:10:00',
    deviceName: 'D区-01号柜',
    deviceCode: 'XL-010',
    type: 'offline',
    status: 'resolved'
  }
]

const getTypeTag = (type: AlarmItem['type']) => {
  const config = {
    offline: { color: 'error', text: '设备掉线' },
    cell_fault: { color: 'warning', text: '格口故障' },
    heartbeat_timeout: { color: 'info', text: '心跳超时' }
  }
  const { color, text } = config[type]
  return <Tag color={color}>{text}</Tag>
}

const getStatusTag = (status: AlarmItem['status']) => {
  return status === 'pending' ? <Tag color="error">待处理</Tag> : <Tag color="success">已解决</Tag>
}

interface RecentAlarmsProps {
  loading?: boolean
}

const RecentAlarms: React.FC<RecentAlarmsProps> = ({ loading = false }) => {
  const { styles } = useStyles()
  const navigate = useNavigate()

  const columns: ColumnsType<AlarmItem> = [
    {
      title: '告警时间',
      dataIndex: 'time',
      key: 'time',
      width: 140,
      render: time => <span className={styles.timeCell}>{time}</span>
    },
    {
      title: '设备名称',
      dataIndex: 'deviceName',
      key: 'deviceName',
      ellipsis: true
    },
    {
      title: '告警类型',
      dataIndex: 'type',
      key: 'type',
      width: 100,
      render: type => getTypeTag(type)
    },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      width: 80,
      render: status => getStatusTag(status)
    }
  ]

  return (
    <Card
      className={styles.card}
      loading={loading}
      variant="borderless"
      title={
        <div className={styles.cardHeader}>
          <span className={styles.cardTitle}>近期告警</span>
          <Button type="link" className={styles.linkBtn} onClick={() => navigate('/device/alarm')}>
            查看更多 <RightOutlined style={{ fontSize: 10 }} />
          </Button>
        </div>
      }
    >
      <Table
        className={styles.table}
        columns={columns}
        dataSource={mockAlarms}
        rowKey="id"
        pagination={false}
        size="small"
      />
    </Card>
  )
}

export default RecentAlarms
