import React, { useEffect, useState, useMemo } from 'react'
import { Outlet, matchRoutes, useLocation, useNavigate } from 'react-router-dom'
import { observer } from 'mobx-react'
import { useAsyncEffect } from 'ahooks'
import { Button, Dropdown, MenuProps } from 'antd'
import { MoonOutlined, SunOutlined, UserOutlined } from '@ant-design/icons'
import { PageContainer, ProLayout, ProBreadcrumb } from '@ant-design/pro-components'

import { RouteType, router } from '@/routes'
import { routers } from '@/routes/routers'
import defaultProps from '@/_defaultProps'
import Settings from '@config/defaultSettings'

import { storeGlobalUser } from '@/store/globalUser'
import { storage } from '@/utils/Storage'
import { session } from '@/utils/Session'
import { redirectToHome } from '@/utils'
import { useThemeSwitcher } from '@/hooks/useThemeSwitcher'
import { logout } from '@/apis/admin/site'

import ChangePasswordModal from '@/components/ChangePasswordModal'
import PageLoading from '@/components/PageLoading'

import Logo from '@/assets/logo.jpg'

export enum ComponTypeEnum {
  MENU,
  PAGE
}

export const GlobalUserInfo = React.createContext<Partial<AdminUser.UserInfoResponse> & {
  isDarkMode?: boolean
  permissions?: string[]
  hasPermission?: (perm: string) => boolean
}>({})
const BasicLayout: React.FC = () => {
  const [pathname, setPathname] = useState(window.location.pathname)
  const { isDarkMode, toggleTheme } = useThemeSwitcher()
  const navigate = useNavigate()
  const location = useLocation()
  const matchRoute = matchRoutes(routers, location)
  const [showLayout, setShowLayout] = useState(false)
  const [loading, setLoading] = useState(true)

  // 在ProLayout中添加主题切换按钮
  const renderThemeToggle = () => (
    <Button
      style={{
        marginLeft: 8
      }}
      key="theme"
      onClick={toggleTheme}
      shape="circle"
      icon={isDarkMode ? <SunOutlined /> : <MoonOutlined />}
    />
  )
  /**
   * 处理菜单权限隐藏菜单
   * 兼容本地菜单和动态菜单两种方式
   */
  const reduceRouter = (r: RouteType[]): RouteType[] => {
    // 如果使用了后端动态菜单，优先使用权限标识检查
    if (storeGlobalUser.menuTree.length > 0) {
      const userPermissions = storeGlobalUser.permissions
      return r?.map(item => {
        // 检查菜单是否有权限标识要求
        const hasPermission = !item.permissionKey ||
          userPermissions.includes(item.permissionKey) ||
          storeGlobalUser.userInfo?.roleId === 1 // 超级管理员有所有权限

        if (item?.children) {
          const { children, ...extra } = item
          const filteredChildren = reduceRouter(item?.children)
          return {
            ...extra,
            routes: filteredChildren,
            hideInMenu: item?.hideInMenu || !hasPermission || filteredChildren.every(c => c.hideInMenu)
          }
        }
        return {
          ...item,
          hideInMenu: item?.hideInMenu || !hasPermission
        }
      }) as any
    }

    // 使用本地菜单的权限过滤逻辑（基于角色）
    const authMenus = storeGlobalUser?.userInfo?.menus
      ?.filter(item => item?.type === ComponTypeEnum.MENU || item?.type === ComponTypeEnum.PAGE)
      ?.map(item => item?.name)
    return r?.map(item => {
      if (item?.children) {
        const { children, ...extra } = item
        return {
          ...extra,
          routes: reduceRouter(item?.children),
          hideInMenu:
            item?.hideInMenu || !item?.children?.find(citem => authMenus?.includes(citem?.name || ''))
        }
      }
      return {
        ...item,
        hideInMenu: item?.hideInMenu || !authMenus?.includes(item?.name || '')
      }
    }) as any
  }

  /**
   * 将后端菜单树转换为 ProLayout 路由格式
   */
  const convertBackendMenuToRoute = (menuTree: AdminUser.MenuTreeDto[]): RouteType[] => {
    const convert = (menus: AdminUser.MenuTreeDto[]): RouteType[] => {
      return menus
        .filter(menu => menu.status === 1) // 只显示启用的菜单
        .sort((a, b) => a.sort - b.sort)
        .map(menu => ({
          name: menu.name,
          path: menu.path,
          icon: menu.icon,
          // 映射组件路径
          component: menu.component,
          // 权限标识
          permissionKey: menu.permKey,
          // 递归处理子菜单
          children: menu.children?.length ? convert(menu.children) : undefined
        }))
    }
    return convert(menuTree)
  }


  useEffect(() => {
    setPathname(window.location.pathname)
    setShowLayout(!matchRoute?.[matchRoute?.length - 1]?.route?.hideLayout)
  }, [window.location.pathname])

  useAsyncEffect(async () => {
    const token = storage.get('token') || session.get('token')
    if (!token) {
      navigate('/login', { replace: true })
    } else if (pathname !== '/login' && token) {
      await storeGlobalUser.getUserDetail()
      if (pathname === '/') {
        redirectToHome(storeGlobalUser?.userInfo?.roleId, navigate)
      }
      setLoading(false)
    }
  }, [])

  const items: MenuProps['items'] = [
    {
      key: 'out',
      label: (
        <div
          onClick={() => {
            logout().then(() => {
              storage.clear()
              navigate('/login', { replace: true })
            })
          }}
        >
          退出登录
        </div>
      )
    }
  ]

  /**
   * 获取有效的菜单数据
   * 优先使用后端返回的菜单树，否则使用本地菜单
   */
  const menuData = useMemo(() => {
    if (storeGlobalUser.menuTree.length > 0) {
      // 使用后端返回的动态菜单
      const backendRoutes = convertBackendMenuToRoute(storeGlobalUser.menuTree)
      return {
        ...router,
        routes: [{
          ...router.routes[0],
          routes: backendRoutes
        }]
      }?.routes?.[0]
    }
    // 使用本地菜单（带权限过滤）
    return reduceRouter(router?.routes)?.[0]
  }, [storeGlobalUser.menuTree, storeGlobalUser.permissions, storeGlobalUser.userInfo])
  return (
    <>
      {loading ? <div style={{ width: '100%', height: '100vh' }}><PageLoading /></div> :
        <GlobalUserInfo.Provider value={{
          ...storeGlobalUser.userInfo,
          isDarkMode,
          permissions: storeGlobalUser.permissions,
          hasPermission: storeGlobalUser.hasPermission.bind(storeGlobalUser)
        }}>
          {showLayout ? (
            <ProLayout
              {...defaultProps}
              className="root-pro-layout"
              navTheme={isDarkMode ? 'realDark' : 'light'}
              logo={Logo}
              route={menuData}
              headerContentRender={() => <ProBreadcrumb />}
              location={{ pathname }}
              actionsRender={() => [<ChangePasswordModal key="password" />, renderThemeToggle()]}
              avatarProps={{
                src: <UserOutlined style={{ fontSize: '16px', color: '#08c' }} />,
                size: 'small',
                title: storeGlobalUser.userInfo?.userName,
                render: (_, defaultDom) => {
                  return <Dropdown menu={{ items }}>{defaultDom}</Dropdown>
                }
              }}
              menuProps={{
                theme: isDarkMode ? 'dark' : 'light',
                onClick: ({ key }) => {
                  navigate(key || '/')
                }
              }}
              {...Settings}
            >
              <PageContainer breadcrumbRender={false} title={false} className="root-pro-container">
                <Outlet />
              </PageContainer>
            </ProLayout>
          ) : (
            <Outlet />
          )}
        </GlobalUserInfo.Provider>
      }
    </>
  )
}

export default observer(BasicLayout)


