import { Card, Button, Row, Col } from 'antd'
import { Pie } from '@ant-design/plots'
import { DatabaseOutlined, RightOutlined } from '@ant-design/icons'
import { createStyles } from 'antd-style'
import { useNavigate } from 'react-router-dom'
import { useContext } from 'react'
import { GlobalUserInfo } from '@/layout/BasicLayout'

const useStyles = createStyles(({ token, isDarkMode }) => ({
  card: {
    borderRadius: '12px',
  },
  cardHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  cardTitle: {
    fontSize: '16px',
    fontWeight: 600,
    color: token.colorTextHeading,
    display: 'flex',
    alignItems: 'center',
    gap: '8px',
  },
  linkBtn: {
    fontSize: '12px',
    padding: 0,
  },
  content: {
    display: 'flex',
    alignItems: 'center',
    gap: '24px',
  },
  chartWrapper: {
    flex: '0 0 300px',
  },
  statsWrapper: {
    flex: 1,
  },
  statCard: {
    textAlign: 'center',
    padding: '24px 16px',
    borderRadius: '12px',
    border: `1px solid ${token.colorBorder}`,
    transition: 'all 0.3s ease',
    '&:hover': {
      transform: 'translateY(-4px)',
      boxShadow: isDarkMode
        ? '0 8px 24px rgba(0, 0, 0, 0.4)'
        : '0 8px 24px rgba(0, 0, 0, 0.08)',
    },
  },
  onlineCard: {
    background: isDarkMode
      ? 'linear-gradient(135deg, rgba(16,185,129,0.15) 0%, rgba(16,185,129,0.05) 100%)'
      : 'linear-gradient(135deg, #DBEAFE 0%, #EFF6FF 100%)',
    borderColor: isDarkMode ? '#059669' : '#BFDBFE',
  },
  offlineCard: {
    background: isDarkMode
      ? 'linear-gradient(135deg, rgba(148,163,184,0.15) 0%, rgba(148,163,184,0.05) 100%)'
      : 'linear-gradient(135deg, #F1F5F9 0%, #F8FAFC 100%)',
    borderColor: isDarkMode ? '#475569' : '#E2E8F0',
  },
  faultCard: {
    background: isDarkMode
      ? 'linear-gradient(135deg, rgba(239,68,68,0.15) 0%, rgba(239,68,68,0.05) 100%)'
      : 'linear-gradient(135deg, #FEE2E2 0%, #FEF2F2 100%)',
    borderColor: isDarkMode ? '#DC2626' : '#FECACA',
  },
  statValue: {
    fontSize: '36px',
    fontWeight: 700,
    marginBottom: '8px',
  },
  onlineValue: {
    color: '#2563EB',
  },
  offlineValue: {
    color: '#64748B',
  },
  faultValue: {
    color: '#EF4444',
  },
  statLabel: {
    fontSize: '14px',
    color: token.colorText,
    fontWeight: 500,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '6px',
  },
  indicator: {
    width: '8px',
    height: '8px',
    borderRadius: '50%',
  },
  onlineIndicator: {
    background: '#10B981',
  },
  offlineIndicator: {
    background: '#CBD5E1',
  },
  faultIndicator: {
    background: '#EF4444',
  },
  statPercent: {
    fontSize: '12px',
    color: token.colorTextSecondary,
    marginTop: '4px',
  },
  responsiveRow: {
    '@media (max-width: 1200px)': {
      flexDirection: 'column' as const,
    },
  },
}))

interface DeviceStatusData {
  type: string
  value: number
  color: string
}

interface DeviceStatusOverviewProps {
  loading?: boolean
  onlineNum?: number
  offlineNum?: number
  faultNum?: number
}

const DeviceStatusOverview: React.FC<DeviceStatusOverviewProps> = ({
  loading = false,
  onlineNum = 0,
  offlineNum = 0,
  faultNum = 0
}) => {
  // 使用传入的数据
  const deviceData: DeviceStatusData[] = [
    { type: '在线', value: onlineNum, color: '#10B981' },
    { type: '离线', value: offlineNum, color: '#CBD5E1' },
    { type: '故障', value: faultNum, color: '#EF4444' },
  ]

  const totalDevices = onlineNum + offlineNum + faultNum
  const { styles, cx } = useStyles()
  const { isDarkMode } = useContext(GlobalUserInfo)
  const navigate = useNavigate()

  const pieConfig = {
    data: deviceData,
    angleField: 'value',
    colorField: 'type',
    color: deviceData.map(d => d.color),
    radius: 0.85,
    innerRadius: 0.65,
    height: 220,
    label: false,
    legend: {
      position: 'right',
      layout: 'vertical',
      itemSpacing: 16,
      itemName: {
        style: {
          fontSize: 13,
        },
      },
    },
    tooltip: {
      formatter: (datum: DeviceStatusData) => {
        const percent = ((datum.value / totalDevices) * 100).toFixed(0)
        return {
          name: datum.type,
          value: `${datum.value}台 (${percent}%)`,
        }
      },
    },
    annotations: [
      {
        type: 'text',
        position: ['50%', '50%'],
        content: `${totalDevices}`,
        style: {
          fontSize: 28,
          fontWeight: 700,
          fill: isDarkMode ? '#fff' : '#1E293B',
          textAlign: 'center',
        },
      },
      {
        type: 'text',
        position: ['50%', '65%'],
        content: '总设备',
        style: {
          fontSize: 12,
          fill: isDarkMode ? '#94a3b8' : '#64748B',
          textAlign: 'center',
        },
      },
    ],
  }

  return (
    <Card
      className={styles.card}
      loading={loading}
      variant="borderless"
      title={
        <div className={styles.cardHeader}>
          <span className={styles.cardTitle}>
            <DatabaseOutlined style={{ color: '#2563EB' }} />
            设备状态概览
          </span>
          <Button
            type="link"
            className={styles.linkBtn}
            onClick={() => navigate('/device/list')}
          >
            查看全部设备 <RightOutlined style={{ fontSize: 10 }} />
          </Button>
        </div>
      }
    >
      <Row gutter={[24, 24]} align="middle">
        <Col xs={24} lg={8}>
          <div className={styles.chartWrapper}>
            <Pie {...pieConfig} />
          </div>
        </Col>
        <Col xs={24} lg={16}>
          <Row gutter={[16, 16]}>
            <Col xs={24} sm={8}>
              <div className={cx(styles.statCard, styles.onlineCard)}>
                <div className={cx(styles.statValue, styles.onlineValue)}>{onlineNum}</div>
                <div className={styles.statLabel}>
                  <span className={cx(styles.indicator, styles.onlineIndicator)} />
                  在线设备
                </div>
                <div className={styles.statPercent}>
                  占比 {totalDevices > 0 ? ((onlineNum / totalDevices) * 100).toFixed(0) : 0}%
                </div>
              </div>
            </Col>
            <Col xs={24} sm={8}>
              <div className={cx(styles.statCard, styles.offlineCard)}>
                <div className={cx(styles.statValue, styles.offlineValue)}>{offlineNum}</div>
                <div className={styles.statLabel}>
                  <span className={cx(styles.indicator, styles.offlineIndicator)} />
                  离线设备
                </div>
                <div className={styles.statPercent}>
                  占比 {totalDevices > 0 ? ((offlineNum / totalDevices) * 100).toFixed(0) : 0}%
                </div>
              </div>
            </Col>
            <Col xs={24} sm={8}>
              <div className={cx(styles.statCard, styles.faultCard)}>
                <div className={cx(styles.statValue, styles.faultValue)}>{faultNum}</div>
                <div className={styles.statLabel}>
                  <span className={cx(styles.indicator, styles.faultIndicator)} />
                  故障设备
                </div>
                <div className={styles.statPercent}>
                  占比 {totalDevices > 0 ? ((faultNum / totalDevices) * 100).toFixed(0) : 0}%
                </div>
              </div>
            </Col>
          </Row>
        </Col>
      </Row>
    </Card>
  )
}

export default DeviceStatusOverview
