import { Card, Table, Tag, Button } from 'antd'
import { RightOutlined } from '@ant-design/icons'
import { createStyles } from 'antd-style'
import type { ColumnsType } from 'antd/es/table'
import { useNavigate } from 'react-router-dom'

const useStyles = createStyles(({ token }) => ({
  card: {
    borderRadius: '12px',
    height: '100%'
  },
  cardHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '16px'
  },
  cardTitle: {
    fontSize: '16px',
    fontWeight: 600,
    color: token.colorTextHeading
  },
  linkBtn: {
    fontSize: '12px',
    padding: 0
  },
  table: {
    '& .ant-table-cell': {
      fontSize: '13px',
      padding: '12px 8px'
    }
  },
  orderId: {
    fontSize: '12px',
    fontFamily: 'monospace',
    color: token.colorTextSecondary
  },
  timeCell: {
    fontSize: '12px',
    color: token.colorTextSecondary
  }
}))

interface OrderItem {
  id: string
  type: 'store' | 'pickup'
  deviceName: string
  deviceCode: string
  time: string
  status: 'pending' | 'completed' | 'overdue'
}

// 模拟数据
const mockOrders: OrderItem[] = [
  {
    id: 'ORD20260403001',
    type: 'store',
    deviceName: 'A区-01号柜',
    deviceCode: 'XL-001',
    time: '09:30:00',
    status: 'completed'
  },
  {
    id: 'ORD20260403002',
    type: 'pickup',
    deviceName: 'B区-02号柜',
    deviceCode: 'XL-002',
    time: '09:15:00',
    status: 'completed'
  },
  {
    id: 'ORD20260403003',
    type: 'store',
    deviceName: 'C区-03号柜',
    deviceCode: 'XL-003',
    time: '08:45:00',
    status: 'pending'
  },
  {
    id: 'ORD20260403004',
    type: 'pickup',
    deviceName: 'A区-05号柜',
    deviceCode: 'XL-005',
    time: '08:20:00',
    status: 'completed'
  },
  {
    id: 'ORD20260403005',
    type: 'store',
    deviceName: 'D区-01号柜',
    deviceCode: 'XL-010',
    time: '07:55:00',
    status: 'overdue'
  }
]

const getTypeTag = (type: OrderItem['type']) => {
  return type === 'store' ? <Tag color="blue">存件</Tag> : <Tag color="green">取件</Tag>
}

const getStatusTag = (status: OrderItem['status']) => {
  const config = {
    pending: { color: 'warning', text: '进行中' },
    completed: { color: 'success', text: '已完成' },
    overdue: { color: 'error', text: '已逾期' }
  }
  const { color, text } = config[status]
  return <Tag color={color}>{text}</Tag>
}

interface RecentOrdersProps {
  loading?: boolean
}

const RecentOrders: React.FC<RecentOrdersProps> = ({ loading = false }) => {
  const { styles } = useStyles()
  const navigate = useNavigate()

  const columns: ColumnsType<OrderItem> = [
    {
      title: '订单号',
      dataIndex: 'id',
      key: 'id',
      width: 130,
      render: id => <span className={styles.orderId}>{id}</span>
    },
    {
      title: '类型',
      dataIndex: 'type',
      key: 'type',
      width: 70,
      render: type => getTypeTag(type)
    },
    {
      title: '柜机',
      dataIndex: 'deviceName',
      key: 'deviceName',
      ellipsis: true
    },
    {
      title: '时间',
      dataIndex: 'time',
      key: 'time',
      width: 80,
      render: time => <span className={styles.timeCell}>{time}</span>
    },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      width: 80,
      render: status => getStatusTag(status)
    }
  ]

  return (
    <Card
      className={styles.card}
      loading={loading}
      variant="borderless"
      title={
        <div className={styles.cardHeader}>
          <span className={styles.cardTitle}>近期订单</span>
          <Button type="link" className={styles.linkBtn} onClick={() => navigate('/order/list')}>
            查看更多 <RightOutlined style={{ fontSize: 10 }} />
          </Button>
        </div>
      }
    >
      <Table
        className={styles.table}
        columns={columns}
        dataSource={mockOrders}
        rowKey="id"
        pagination={false}
        size="small"
      />
    </Card>
  )
}

export default RecentOrders
