/**
 * 文件上传服务
 * @param data 上传文件数据
 */
export const uploadImage = (data: FormData) =>
  Axios.request<Result<SiteTypes.ImageUploadRes>>({
    url: '/admin/common-upload/images/commit',
    method: 'POST',
    data,
    headers: {
      'Content-Type': 'multipart/form-data'
    }
  })

